import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2023-03-02","description":"","frontmatter":{"title":"Ceph Performance Meeting 2023-03-02","date":"2023-03-02T00:00:00.000Z","updated":"2023-03-07T00:00:00.000Z","tags":["Ceph","性能优化","RocksDB","PR审查","存储集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Performance_Meeting_2023-03-02.md","filePath":"posts/2023/Ceph_Performance_Meeting_2023-03-02.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Performance_Meeting_2023-03-02.md"};function s(n,l,p,g,a,_){return i(),t("div",null,[...l[0]||(l[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议概述</strong></p><p>本次会议于2023年3月2日召开，主要回顾了最近两周的Pull Request（PR）审查进度，并讨论了多个关键议题，包括RocksDB更新、PR审查、新的基准测试工具、读取平衡器性能改进以及QAT加密性能问题。会议还决定了后续行动计划。</p><p><strong>主要讨论议题</strong></p><ol><li><p><strong>PR审查进度</strong></p><ul><li>主持人接近完成PR列表的审查，但尚未完全完成。</li><li>讨论了Casey关于在rgw中切换回多态执行器的PR，Mark Hogan进行了测试，未发现明显的性能提升，但仍计划在Reef之后进行切换。</li></ul></li><li><p><strong>已关闭的PR</strong></p><ul><li>讨论了Igor的一个csq更改，使用更大的读取块在cue列表条目中，预计会有小的性能改进。</li><li>讨论了关于更新Facebook的RocksDB的PR。</li></ul></li><li><p><strong>新的和更新的PR</strong></p><ul><li>讨论了替换RBD配置的PR，加密添加qat批处理的PR等。</li></ul></li><li><p><strong>RocksDB更新</strong></p><ul><li>讨论了RocksDB的更新，该更新在现有的Valgrind测试中失败，但通过添加大量新的Valgrind抑制规则使其通过。计划在接下来的几个月中进行大量测试，如果出现问题，可能会回滚。</li></ul></li><li><p><strong>新的基准测试工具</strong></p><ul><li>讨论了一个新的基准测试工具，该工具使用了许多底层库，如librbd等，并自动填充Google表格与基准测试结果。但需要更多的测试和与现有工具如fio的比较。</li></ul></li><li><p><strong>读取平衡器</strong></p><ul><li>讨论了读取平衡器的性能改进，计划在一个小集群上进行测试，以证明性能的实际改进。</li></ul></li><li><p><strong>QAT加密问题</strong></p><ul><li>讨论了QAT加密的性能问题，特别是关于是否需要在插件中进行等待的设计问题。</li></ul></li></ol><p><strong>决定事项</strong></p><ul><li>计划在Reef之后切换回多态执行器。</li><li>RocksDB的更新将在接下来的几个月中进行大量测试，如果出现问题，可能会回滚。</li><li>将进行一个小集群的测试，以证明读取平衡器的性能改进。</li><li>将进行QAT加密的性能测试，以评估是否需要进行等待。</li></ul><p><strong>后续行动计划</strong></p><ul><li>继续完成PR列表的审查。</li><li>进行RocksDB的更新测试，并监控内存泄漏和其他问题。</li><li>进行新的基准测试工具的测试，并与现有工具进行比较。</li><li>在小集群上进行读取平衡器的性能测试。</li><li>进行QAT加密的性能测试，以评估是否需要进行等待。</li></ul><p><strong>其他讨论</strong></p><ul><li>讨论了关于Spinner设置的首次写入问题，建议尝试禁用首次写入以减少开销。</li><li>讨论了Blue Store的日志问题，建议尝试使用新的日志实现来减少对RocksDB的依赖。</li></ul><p><strong>会议结束</strong></p><p>会议在讨论了所有议题后结束，感谢所有参与者的贡献，并期待下一次会议。</p>",13)])])}const R=e(r,[["render",s]]);export{u as __pageData,R as default};
